import urllib.request
from hashlib import sha256
def task_func(url):
    try:
        (pub_key, priv_key) = rsa.newkeys(512, poolsize=2)

        response = urllib.request.urlopen(url)
        content = response.read()
        if not content:
            raise ValueError("No content retrieved from the URL")

        hash_value = sha256(content).digest()

        signed_hash = rsa.sign(hash_value, priv_key, 'SHA-256').hex()
        if not signed_hash:
            raise rsa.pkcs1.VerificationError("Failed to generate a valid signed hash.")

        return pub_key, signed_hash, hash_value
    except urllib.error.HTTPError as e:
        raise urllib.error.HTTPError(url, e.code, f"Server returned HTTP error: {e.reason}", e.hdrs, e.fp)
    except urllib.error.URLError as e:
        raise ValueError(f"Failed to reach the server due to an invalid or unreachable URL: {e.reason}")
    except rsa.pkcs1.VerificationError as e:
        raise rsa.pkcs1.VerificationError(f"Error in signing the hash: {e}")

