import subprocess
import os
import threading
def task_func(script_path: str, timeout: int = 60) -> str:
    try:
        if not os.path.isfile(script_path):
            raise FileNotFoundError(f"The file {script_path} does not exist.")

        def execute_script():
            process = subprocess.Popen(script_path, shell=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
            process.communicate()

        thread = threading.Thread(target=execute_script)
        thread.start()
        thread.join(timeout)

        if thread.is_alive():
            process.terminate()
            return "Terminating process due to timeout."
        else:
            return "Script executed successfully."
    except FileNotFoundError as e:
        return str(e)

