import itertools
import math
from pandas import Series
def task_func(elements, subset_size, top_n=2):
    if subset_size > len(elements):
        return 1, Series([])
    elif subset_size == 0:
        return 1, Series([])
    else:
        subsets = list(itertools.combinations(elements, subset_size))
        sums = [sum(subset) for subset in subsets]
        sums_series = Series(sums)
        sums_series = sums_series.sort_values(ascending=False)
        top_n_sums = sums_series.iloc[:top_n]
        product_of_sums = math.prod(sums)
        return product_of_sums, top_n_sums.tolist()

