import re
import os
import shutil
from datetime import datetime
def task_func(directory):

    organized_files = {}
    for filename in os.listdir(directory):
        filepath = os.path.join(directory, filename)
        if os.path.isfile(filepath):
            text = re.search(r"(?<=\[)[^\]]*(?=\])", filename)
            if text:
                text = text.group(0)
                if not os.path.exists(os.path.join(directory, text)):
                    os.mkdir(os.path.join(directory, text))
                new_filepath = os.path.join(directory, text, filename)
                shutil.move(filepath, new_filepath)
                if text in organized_files:
                    organized_files[text].append(filename)
                else:
                    organized_files[text] = [filename]
            else:
                continue
    return directory, organized_files

