import time
def task_func(script_path, wait=True, *args):
    # Check if script exists
    if not os.path.isfile(script_path):
        raise ValueError(f"Script '{script_path}' does not exist.")

    try:
        # Run script in a background process
        process = subprocess.Popen(
            [sys.executable, script_path, *args], 
            stderr=subprocess.PIPE,
            stdout=subprocess.PIPE,
        )

        # Wait for the process to complete if required
        if wait:
            stdout, stderr = process.communicate()
            if stderr and b"Exception" in stderr:
                raise subprocess.CalledProcessError(
                    1, 
                    [sys.executable, script_path, *args]
                )
            return process.returncode
        return None

    except Exception as e:
        if not isinstance(e, subprocess.CalledProcessError):
            raise subprocess.CalledProcessError(1, [sys.executable, script_path, *args]) from e
