from docx import Document
def task_func(directory_path: str) -> int:

    # Get all .docx files in the directory
    files = glob.glob(directory_path + '/*.docx')

    # Process each file
    for file in files:
        doc = Document(file)

        # Protect all double quotes in the text
        for paragraph in doc.paragraphs:
            if paragraph.text:
                paragraph.text = re.sub(r'"', r'\"', paragraph.text)

        # Save the changes
        doc.save(file)

    return len(files)

