def task_func(df: pd.DataFrame, column_name: str, pattern: str) -> pd.DataFrame:
    def reverse_matched_words(text):
        if not text: 
            return text

        words = text.split()

        positions = [bool(re.search(pattern, word)) for word in words]
        matched_words = [word for word in words if re.search(pattern, word)]

        matched_words.reverse()

        result = []
        matched_idx = 0
        for i, word in enumerate(words):
            if positions[i]:
                result.append(matched_words[matched_idx])
                matched_idx += 1
            else:
                result.append(word)

        return " ".join(result)

    if not pattern:
        return df.copy()

    new_df = df.copy()
    new_df[column_name] = new_df[column_name].apply(reverse_matched_words)
    return new_df

