import random

def task_func(text: str, seed=None) -> str:
    if seed is not None:
        random.seed(seed)

    text = re.sub("[%s]" % re.escape(string.punctuation), "", text)

    REPLACEMENTS = {" ": "_", "\t": "__", "\n": "___"}
